"use strict";
// What the pantry hands out, and a note of every question a watched shelf
// is asked.
const notes = [];

class Jar {
  constructor(label) {
    this.label = label;
    this.grams = 250;
  }
  weigh() {
    return this.grams;
  }
}
Jar.prototype.shelf = "top";

class SpiceJar extends Jar {
  constructor(label) {
    super(label);
    this.heat = 3;
  }
}
SpiceJar.prototype.rack = "door";

function* restock() {
  yield "flour";
  yield "rice";
}

function recipe() {
  return "bread";
}
recipe.serves = 4;
recipe.minutes = 50;

const watched = (target) =>
  new Proxy(target, {
    ownKeys(t) {
      notes.push("keys");
      return Reflect.ownKeys(t);
    },
    getOwnPropertyDescriptor(t, key) {
      notes.push("look:" + String(key));
      return Reflect.getOwnPropertyDescriptor(t, key);
    },
    getPrototypeOf(t) {
      notes.push("parent");
      return Reflect.getPrototypeOf(t);
    },
    has(t, key) {
      notes.push("has:" + String(key));
      return key in t;
    },
  });

exports.stock = () => ({ oats: 2, beans: 1, 12: "dozen", 3: "trio" });
exports.inherited = () => Object.assign(Object.create({ salt: 1, oats: 9 }), { oats: 2, tea: 5 });
exports.jar = () => new SpiceJar("cumin");
exports.list = () => ["flour", "rice", "lentils"];
exports.restock = restock;
exports.recipe = () => recipe;
exports.hidden = () => {
  const shelf = Object.create({ unseen: 0, below: 1 });
  shelf.seen = 1;
  Object.defineProperty(shelf, "unseen", { value: 2, enumerable: false });
  return shelf;
};
exports.picked = () => new Proxy({ a: 1, b: 2, c: 3 }, { ownKeys: () => ["c", "a"] });
exports.watched = () => watched({ mint: 1, sage: 2 });
exports.watchedBelow = () => Object.assign(Object.create(watched({ deep: 1 })), { top: 1 });
exports.locked = () =>
  new Proxy(
    {},
    {
      ownKeys() {
        throw new Error("the pantry is locked");
      },
    },
  );
exports.odd = () => ({ "two words": 1, "café": 2, 'a "quoted" one': 3, "": 4, "back\\slash": 5 });
exports.remove = (shelf, key) => {
  delete shelf[key];
};
exports.put = (shelf, key) => {
  shelf[key] = 1;
};
exports.dim = (shelf, key) => {
  Object.defineProperty(shelf, key, { enumerable: false });
};
exports.visit = (walk) => walk(exports.stock());
exports.walk = (shelf) => {
  const seen = [];
  for (const key in shelf) seen.push(key);
  return seen.join(",");
};
exports.notes = () => notes.splice(0).join(" ");
